import sqlite3, os
db = os.path.expanduser(r"~\.openviking\data\_system\usage_audit\usage_audit.sqlite3")
con = sqlite3.connect(f"file:{db}?mode=ro", uri=True); cur=con.cursor()
def q(t,s,a=()):
    print("\n==== "+t+" ===="); 
    try:
        cur.execute(s,a); r=cur.fetchall()
        for x in r: print(x)
        if not r: print("(none)")
    except Exception as e: print("ERR",e)

q("token usage by source/provider/model", "SELECT source, provider, model_name, token_type, SUM(token_count) total, COUNT(*) buckets FROM usage_token_hourly GROUP BY source,provider,model_name,token_type ORDER BY total DESC")
q("token usage by date", "SELECT date_utc, SUM(token_count) FROM usage_token_hourly GROUP BY date_utc ORDER BY date_utc DESC LIMIT 15")
